  const clusteredErrors = useMemo(() => {
    if (!showErrorClustering) return [];
    
    const errorGroups: Record<string, { 
      errorMessage: string, 
      errorType: string, 
      pipelines: Set<string>, 
      jobs: any[] 
    }> = {};

    jobs.forEach(job => {
      if (job.status.includes('Error') && job.error) {
        const key = job.error;
        if (!errorGroups[key]) {
          errorGroups[key] = {
            errorMessage: job.error,
            errorType: job.errorType || 'Unknown',
            pipelines: new Set(),
            jobs: []
          };
        }
        errorGroups[key].pipelines.add(job.pipeline);
        errorGroups[key].jobs.push(job);
      }
    });

    return Object.values(errorGroups).map(group => {
      const pipelineCounts: Record<string, number> = {};
      group.jobs.forEach(job => {
        pipelineCounts[job.pipeline] = (pipelineCounts[job.pipeline] || 0) + 1;
      });
      const isInfrastructureWide = Object.values(pipelineCounts).some(count => count >= 3);

      return {
        ...group,
        pipelineCount: group.pipelines.size,
        isInfrastructureWide
      };
    }).sort((a, b) => b.pipelineCount - a.pipelineCount);
  }, [jobs, showErrorClustering]);

