  const handleSaveConfig = async () => {
    if (!newConfigName.trim() || !user) return;
    setIsSavingConfig(true);
    try {
      const configData = {
        name: newConfigName.trim(),
        timestamp: new Date().toISOString(),
        features: featuresData.map(f => ({
          id: f.id,
          effort: f.effort || 0,
          need: f.need || 0
        })),
        toggles: {
          showSupportTickets,
          showSupportPerformance,
          showJiraIntegration,
          showAutomatedChangeLog,
          showContainerPipelines,
          showContainerRegistry,
          showVulnerabilityHeatmap,
          showOrphanedDetection,
          showVulnerabilityScan,
          showAdvancedArchitecture,
          showArchitectureDiff,
          showPipelineSidebarDetails,
          showPipelineTypeDropdown,
          showDraftUpdates,
          showDryRunUpdates,
          isFeatureDryRunLogEnabled,
          showReviewerDashboard,
          showErrorClustering,
          isInternalTeamView,
          isReviewerView,
          isEditingDraft
        }
      };
      await addDoc(collection(db, 'featureConfigurations'), configData);
      setIsSaveConfigModalOpen(false);
      setNewConfigName('');
    } catch (error) {
      handleFirestoreError(error, OperationType.WRITE, 'featureConfigurations');
    } finally {
      setIsSavingConfig(false);
    }
  };

  const handleLoadConfig = (config: any) => {
    // Update featuresData
    setFeaturesData(prev => prev.map(f => {
      const saved = config.features.find((sf: any) => sf.id === f.id);
      if (saved) {
        const updated = { ...f, effort: saved.effort, need: saved.need };
        updated.score = updated.need * (11 - updated.effort);
        return updated;
      }
      return f;
    }));

    // Update toggles
    const t = config.toggles;
    if (t.showSupportTickets !== undefined) setShowSupportTickets(t.showSupportTickets);
    if (t.showSupportPerformance !== undefined) setShowSupportPerformance(t.showSupportPerformance);
    if (t.showJiraIntegration !== undefined) setShowJiraIntegration(t.showJiraIntegration);
    if (t.showAutomatedChangeLog !== undefined) setShowAutomatedChangeLog(t.showAutomatedChangeLog);
    if (t.showContainerPipelines !== undefined) setShowContainerPipelines(t.showContainerPipelines);
    if (t.showContainerRegistry !== undefined) setShowContainerRegistry(t.showContainerRegistry);
    if (t.showVulnerabilityHeatmap !== undefined) setShowVulnerabilityHeatmap(t.showVulnerabilityHeatmap);
    if (t.showOrphanedDetection !== undefined) setShowOrphanedDetection(t.showOrphanedDetection);
    if (t.showVulnerabilityScan !== undefined) setShowVulnerabilityScan(t.showVulnerabilityScan);
    if (t.showAdvancedArchitecture !== undefined) setShowAdvancedArchitecture(t.showAdvancedArchitecture);
    if (t.showArchitectureDiff !== undefined) setShowArchitectureDiff(t.showArchitectureDiff);
    if (t.showPipelineSidebarDetails !== undefined) setShowPipelineSidebarDetails(t.showPipelineSidebarDetails);
    if (t.showPipelineTypeDropdown !== undefined) setShowPipelineTypeDropdown(t.showPipelineTypeDropdown);
    if (t.showDraftUpdates !== undefined) setShowDraftUpdates(t.showDraftUpdates);
    if (t.showDryRunUpdates !== undefined) setShowDryRunUpdates(t.showDryRunUpdates);
    if (t.isFeatureDryRunLogEnabled !== undefined) setIsFeatureDryRunLogEnabled(t.isFeatureDryRunLogEnabled);
    if (t.showReviewerDashboard !== undefined) setShowReviewerDashboard(t.showReviewerDashboard);
    if (t.showErrorClustering !== undefined) setShowErrorClustering(t.showErrorClustering);
    if (t.isInternalTeamView !== undefined) setIsInternalTeamView(t.isInternalTeamView);
    if (t.isReviewerView !== undefined) setIsReviewerView(t.isReviewerView);
    if (t.isEditingDraft !== undefined) setIsEditingDraft(t.isEditingDraft);

    setIsLoadConfigModalOpen(false);
  };

  const handleDeleteConfig = (config: any, e: React.MouseEvent) => {
    e.stopPropagation();
    setConfigToDelete(config);
  };

  const confirmDeleteConfig = async () => {
    if (!configToDelete) return;
    try {
      await deleteDoc(doc(db, 'featureConfigurations', configToDelete.id));
      setConfigToDelete(null);
      setToast({ message: 'Configuration deleted successfully', type: 'success' });
    } catch (error) {
      handleFirestoreError(error, OperationType.DELETE, `featureConfigurations/${configToDelete.id}`);
    }
  };

  const handleSaveJourney = async () => {
    if (!user) {
      setToast({ message: 'You must be signed in to save changes.', type: 'error' });
      return;
    }
    setIsSavingJourney(true);
    try {
      await setDoc(doc(db, 'settings', 'journeys_content'), {
        journeyIntroduction,
        journeyUserJourney,
        journeyPipelineErrors,
        journeyPipelineUpdates,
        journeyContainerArchitecture,
        journeyDryRunSyntheticData,
        journeyHumanSupport,
        journeyTicketing
      }, { merge: true });
      setIsEditingJourney(false);
      setToast({ message: 'User Journeys saved successfully', type: 'success' });
    } catch (error) {
      handleFirestoreError(error, OperationType.WRITE, 'settings/journeys_content');
    } finally {
      setIsSavingJourney(false);
    }
  };

  const handleSaveOverview = async () => {
    if (!user) {
      setToast({ message: 'You must be signed in to save changes.', type: 'error' });
      return;
    }
    setIsSavingOverview(true);
    try {
      await setDoc(doc(db, 'settings', 'overview'), {
        introduction,
        userFlow,
        designPrinciples,
        resources,
        productExplanation,
        userJourney,
        pipelineErrors,
        pipelineUpdates,
        dryRunSyntheticData,
        humanSupport,
        ticketing,
        containerArchitecture
      }, { merge: true });
      setIsEditingOverview(false);
      setToast({ message: 'Overview saved successfully', type: 'success' });
    } catch (error) {
      handleFirestoreError(error, OperationType.WRITE, 'settings/overview');
    } finally {
      setIsSavingOverview(false);
    }
  };

  const handleExportRequirements = () => {
    let content = '';
    let fileName = '';
    const type = 'application/json';

    if (requirementsTab === 'us') {
      content = JSON.stringify(filteredUserStories, null, 2);
      fileName = 'user_stories.json';
    } else if (requirementsTab === 'features') {
      content = JSON.stringify(filteredFeatures, null, 2);
      fileName = 'feature_list.json';
    } else if (requirementsTab === 'ia') {
      content = JSON.stringify(IA_DATA, null, 2);
      fileName = 'information_architecture.json';
    }

    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleExportRequirementsText = () => {
    let content = '';
    let fileName = '';

    if (requirementsTab === 'features') {
      fileName = 'feature_list.txt';
      content += "PRODUCT FEATURE LIST\n";
      content += "===================\n\n";
      
      groupedFeatures.forEach(([epic, items]: [string, any[]]) => {
        content += `EPIC: ${epic.toUpperCase()}\n`;
        content += `${'='.repeat(epic.length + 6)}\n\n`;
        
        const colWidths = { id: 6, title: 60, type: 20, effort: 7, need: 5, score: 6 };
        
        // Header
        content += `${'ID'.padEnd(colWidths.id)} | ${'Title'.padEnd(colWidths.title)} | ${'Type'.padEnd(colWidths.type)} | ${'Eff'.padEnd(colWidths.effort)} | ${'Need'.padEnd(colWidths.need)} | ${'Score'.padEnd(colWidths.score)}\n`;
        content += `${'-'.repeat(colWidths.id)}-|-${'-'.repeat(colWidths.title)}-|-${'-'.repeat(colWidths.type)}-|-${'-'.repeat(colWidths.effort)}-|-${'-'.repeat(colWidths.need)}-|-${'-'.repeat(colWidths.score)}\n`;
        
        items.forEach(item => {
          const score = (item.effort || 0) * (item.need || 0);
          content += `${(item.id || '').padEnd(colWidths.id)} | ${(item.title || '').substring(0, colWidths.title).padEnd(colWidths.title)} | ${(item.type || '').substring(0, colWidths.type).padEnd(colWidths.type)} | ${(item.effort?.toString() || '0').padEnd(colWidths.effort)} | ${(item.need?.toString() || '0').padEnd(colWidths.need)} | ${(score.toString()).padEnd(colWidths.score)}\n`;
          
          if (item.description) {
            content += `   Desc: ${item.description}\n`;
          }
          if (item.capabilities && item.capabilities.length > 0) {
            content += `   Caps: ${item.capabilities.join(', ')}\n`;
          }
          content += "\n";
        });
        content += "\n";
      });
    } else if (requirementsTab === 'us') {
      fileName = 'user_stories.txt';
      content += "PRODUCT USER STORIES\n";
      content += "====================\n\n";
      
      groupedUserStories.forEach(([epic, items]: [string, any[]]) => {
        content += `EPIC: ${epic.toUpperCase()}\n`;
        content += `${'='.repeat(epic.length + 6)}\n\n`;
        
        const colWidths = { id: 7, title: 40, asA: 20, iWant: 45, soThat: 45 };
        
        // Header
        content += `${'ID'.padEnd(colWidths.id)} | ${'Title'.padEnd(colWidths.title)} | ${'As A'.padEnd(colWidths.asA)} | ${'I Want'.padEnd(colWidths.iWant)} | ${'So That'.padEnd(colWidths.soThat)}\n`;
        content += `${'-'.repeat(colWidths.id)}-|-${'-'.repeat(colWidths.title)}-|-${'-'.repeat(colWidths.asA)}-|-${'-'.repeat(colWidths.iWant)}-|-${'-'.repeat(colWidths.soThat)}\n`;
        
        items.forEach(item => {
          content += `${(item.id || '').padEnd(colWidths.id)} | ${(item.title || '').substring(0, colWidths.title).padEnd(colWidths.title)} | ${(item.asA || '').substring(0, colWidths.asA).padEnd(colWidths.asA)} | ${(item.iWant || '').substring(0, colWidths.iWant).padEnd(colWidths.iWant)} | ${(item.soThat || '').substring(0, colWidths.soThat).padEnd(colWidths.soThat)}\n`;
          
          if (item.ac && item.ac.length > 0) {
            content += "   Acceptance Criteria:\n";
            item.ac.forEach((ac: string) => content += `     - ${ac}\n`);
          }
          content += "\n";
        });
        content += "\n";
      });
    }

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.click();
    URL.revokeObjectURL(url);
  };

