  // Data Listeners & Seeding
  useEffect(() => {
    if (!isAuthReady) return;
    
    if (!user) {
      // If not logged in, use initial data
      setFeaturesData(INITIAL_FEATURES);
      setUserStoriesData(INITIAL_USER_STORIES);
      setIsDataLoaded(true);
      return;
    }

    setIsSyncing(true);

    // Listen to features
    const unsubFeatures = onSnapshot(collection(db, 'features'), async (snapshot) => {
      if (snapshot.empty) {
        // Seed if empty
        const batch = writeBatch(db);
        INITIAL_FEATURES.forEach(f => {
          batch.set(doc(db, 'features', f.id), f);
        });
        await batch.commit();
      } else {
        const data = snapshot.docs.map(doc => doc.data() as any);
        // Sort by ID to maintain order
        data.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
        setFeaturesData(data);
      }
    }, (error) => handleFirestoreError(error, OperationType.LIST, 'features'));

    // Listen to datasets
    const unsubDatasets = onSnapshot(collection(db, 'datasets'), async (snapshot) => {
      if (snapshot.empty) {
        const batch = writeBatch(db);
        MOCK_DATASETS.forEach(d => {
          batch.set(doc(db, 'datasets', d.id), d);
        });
        await batch.commit();
      } else {
        const data = snapshot.docs.map(doc => doc.data() as any);
        setDatasets(data);
      }
    }, (error) => handleFirestoreError(error, OperationType.LIST, 'datasets'));

    // Listen to pipelines
    const unsubPipelines = onSnapshot(collection(db, 'pipelines'), async (snapshot) => {
      if (snapshot.empty) {
        const batch = writeBatch(db);
        MOCK_PIPELINES.forEach(p => {
          batch.set(doc(db, 'pipelines', p.id), p);
        });
        await batch.commit();
      } else {
        const data = snapshot.docs.map(doc => doc.data() as Pipeline);
        setPipelines(data);
      }
    }, (error) => handleFirestoreError(error, OperationType.LIST, 'pipelines'));

    // Listen to jobs
    const unsubJobs = onSnapshot(collection(db, 'jobs'), async (snapshot) => {
      if (snapshot.empty) {
        const batch = writeBatch(db);
        MOCK_JOBS.forEach(j => {
          batch.set(doc(db, 'jobs', j.id), j);
        });
        await batch.commit();
      } else {
        const data = snapshot.docs.map(doc => doc.data() as Job);
        setJobs(data);
      }
    }, (error) => handleFirestoreError(error, OperationType.LIST, 'jobs'));

    // Listen to artifacts
    const unsubArtifacts = onSnapshot(collection(db, 'artifacts'), async (snapshot) => {
      if (snapshot.empty) {
        const batch = writeBatch(db);
        MOCK_ARTIFACTS.forEach(a => {
          batch.set(doc(db, 'artifacts', a.id), a);
        });
        await batch.commit();
      } else {
        const data = snapshot.docs.map(doc => doc.data() as Artifact);
        setArtifacts(data);
      }
    }, (error) => handleFirestoreError(error, OperationType.LIST, 'artifacts'));

    // Listen to user stories
    const unsubStories = onSnapshot(collection(db, 'userStories'), async (snapshot) => {
      if (snapshot.empty) {
        // Seed if empty
        const batch = writeBatch(db);
        INITIAL_USER_STORIES.forEach(us => {
          batch.set(doc(db, 'userStories', us.id), us);
        });
        await batch.commit();
      } else {
        const data = snapshot.docs.map(doc => doc.data() as any);
        // Sort by ID
        data.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
        setUserStoriesData(data);
      }
    }, (error) => handleFirestoreError(error, OperationType.LIST, 'userStories'));

    // Listen to settings
    const unsubSettings = onSnapshot(doc(db, 'settings', 'global'), (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.data();
        if (data.visibleColumns) setVisibleColumns(data.visibleColumns);
        if (data.showPipelineSidebarDetails !== undefined) setShowPipelineSidebarDetails(data.showPipelineSidebarDetails);
        if (data.showPipelineTypeDropdown !== undefined) setShowPipelineTypeDropdown(data.showPipelineTypeDropdown);
        if (data.showDraftUpdates !== undefined) setShowDraftUpdates(data.showDraftUpdates);
        if (data.showDryRunUpdates !== undefined) setShowDryRunUpdates(data.showDryRunUpdates);
        if (data.showReviewerDashboard !== undefined) setShowReviewerDashboard(data.showReviewerDashboard);
        if (data.showReadinessAnalysis !== undefined) setShowReadinessAnalysis(data.showReadinessAnalysis);
        if (data.showErrorClustering !== undefined) setShowErrorClustering(data.showErrorClustering);
      }
    }, (error) => handleFirestoreError(error, OperationType.GET, 'settings/global'));

    const unsubConfigs = onSnapshot(collection(db, 'featureConfigurations'), (snapshot) => {
      const configs = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setFeatureConfigs(configs.sort((a: any, b: any) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()));
    }, (error) => handleFirestoreError(error, OperationType.GET, 'featureConfigurations'));

    const unsubOverview = onSnapshot(doc(db, 'settings', 'overview'), (doc) => {
      if (doc.exists()) {
        const data = doc.data();
        if (data.introduction) setIntroduction(data.introduction);
        if (data.userFlow) setUserFlow(data.userFlow);
        if (data.designPrinciples) setDesignPrinciples(data.designPrinciples);
        if (data.resources) setResources(data.resources);
        if (data.productExplanation) setProductExplanation(data.productExplanation);
        if (data.userJourney) setUserJourney(data.userJourney);
        if (data.pipelineErrors) setPipelineErrors(data.pipelineErrors);
        if (data.pipelineUpdates) setPipelineUpdates(data.pipelineUpdates);
        if (data.dryRunSyntheticData) setDryRunSyntheticData(data.dryRunSyntheticData);
        if (data.humanSupport) setHumanSupport(data.humanSupport);
        if (data.ticketing) setTicketing(data.ticketing);
      }
    }, (error) => handleFirestoreError(error, OperationType.GET, 'settings/overview'));

    const unsubJourneys = onSnapshot(doc(db, 'settings', 'journeys_content'), (doc) => {
      if (doc.exists()) {
        const data = doc.data();
        if (data.journeyIntroduction) setJourneyIntroduction(data.journeyIntroduction);
        if (data.journeyUserJourney) setJourneyUserJourney(data.journeyUserJourney);
        if (data.journeyPipelineErrors) setJourneyPipelineErrors(data.journeyPipelineErrors);
        if (data.journeyPipelineUpdates) setJourneyPipelineUpdates(data.journeyPipelineUpdates);
        if (data.journeyContainerArchitecture) setJourneyContainerArchitecture(data.journeyContainerArchitecture);
        if (data.journeyDryRunSyntheticData) setJourneyDryRunSyntheticData(data.journeyDryRunSyntheticData);
        if (data.journeyHumanSupport) setJourneyHumanSupport(data.journeyHumanSupport);
        if (data.journeyTicketing) setJourneyTicketing(data.journeyTicketing);
      }
    }, (error) => handleFirestoreError(error, OperationType.GET, 'settings/journeys_content'));

    setIsDataLoaded(true);
    setIsSyncing(false);

    return () => {
      unsubFeatures();
      unsubStories();
      unsubSettings();
      unsubConfigs();
      unsubOverview();
      unsubJourneys();
      unsubDatasets();
      unsubPipelines();
      unsubJobs();
      unsubArtifacts();
    };
  }, [isAuthReady, user, INITIAL_FEATURES, INITIAL_USER_STORIES]);

  // Sync settings to Firestore
  useEffect(() => {
    if (!user || !isDataLoaded) return;
    const syncSettings = async () => {
      try {
        await setDoc(doc(db, 'settings', 'global'), {
          visibleColumns,
          showPipelineSidebarDetails,
          showPipelineTypeDropdown,
          showDraftUpdates,
          showDryRunUpdates,
          showReviewerDashboard,
          showReadinessAnalysis,
          showErrorClustering
        }, { merge: true });
      } catch (error) {
        console.error("Failed to sync settings", error);
      }
    };
    const timer = setTimeout(syncSettings, 1000);
    return () => clearTimeout(timer);
  }, [
    user, isDataLoaded, visibleColumns, 
    showPipelineSidebarDetails, showPipelineTypeDropdown, 
    showDraftUpdates, showDryRunUpdates, showReviewerDashboard, showReadinessAnalysis, showErrorClustering
  ]);

  const updateFeature = async (id: string, field: 'effort' | 'need', value: number) => {
    const numValue = isNaN(value) ? 0 : value;
    
    // Optimistic update
    setFeaturesData(prev => prev.map(f => {
      if (f.id === id) {
        const updated = { ...f, [field]: numValue };
        // Recalculate score: Score = Need × (11 - Effort)
        const effort = field === 'effort' ? numValue : (updated.effort || 0);
        const need = field === 'need' ? numValue : (updated.need || 0);
        updated.score = need * (11 - effort);
        return updated;
      }
      return f;
    }));

    if (user) {
      try {
        await setDoc(doc(db, 'features', id), { [field]: numValue }, { merge: true });
      } catch (error) {
        handleFirestoreError(error, OperationType.UPDATE, `features/${id}`);
      }
    }
  };

  const handleAddNote = async () => {
    if (!selectedFeatureForNotes || !newNoteText.trim()) return;
    
    const newNote = {
      id: Math.random().toString(36).substring(2, 9),
      text: newNoteText.trim(),
      date: new Date().toISOString(),
      author: user?.email || 'Anonymous'
    };

    const updatedNotes = [...(selectedFeatureForNotes.notes || []), newNote];

    // Optimistic update
    setFeaturesData(prev => prev.map(f => {
      if (f.id === selectedFeatureForNotes.id) {
        return { ...f, notes: updatedNotes };
      }
      return f;
    }));
    
    setSelectedFeatureForNotes({ ...selectedFeatureForNotes, notes: updatedNotes });
    setNewNoteText('');

    if (user) {
      try {
        await setDoc(doc(db, 'features', selectedFeatureForNotes.id), { notes: updatedNotes }, { merge: true });
      } catch (error) {
        handleFirestoreError(error, OperationType.UPDATE, `features/${selectedFeatureForNotes.id}`);
      }
    }
  };

  const handleDeleteNote = async (noteId: string) => {
    if (!selectedFeatureForNotes) return;
    
    const updatedNotes = (selectedFeatureForNotes.notes || []).filter((n: any) => n.id !== noteId);

    // Optimistic update
    setFeaturesData(prev => prev.map(f => {
      if (f.id === selectedFeatureForNotes.id) {
        return { ...f, notes: updatedNotes };
      }
      return f;
    }));
    
    setSelectedFeatureForNotes({ ...selectedFeatureForNotes, notes: updatedNotes });

    if (user) {
      try {
        await setDoc(doc(db, 'features', selectedFeatureForNotes.id), { notes: updatedNotes }, { merge: true });
      } catch (error) {
        handleFirestoreError(error, OperationType.UPDATE, `features/${selectedFeatureForNotes.id}`);
      }
    }
  };

  const handleScoreKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, id: string, field: 'effort' | 'need') => {
    const target = e.target as HTMLInputElement;
    const inputs = Array.from(document.querySelectorAll('.feature-score-input')) as HTMLInputElement[];
    const index = inputs.indexOf(target);

    if (e.key === 'ArrowDown' || e.key === 'Enter') {
      e.preventDefault();
      const nextIndex = index + 2;
      if (nextIndex < inputs.length) {
        inputs[nextIndex].focus();
        inputs[nextIndex].select();
      }
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      const prevIndex = index - 2;
      if (prevIndex >= 0) {
        inputs[prevIndex].focus();
        inputs[prevIndex].select();
      }
    } else if (e.key === 'ArrowRight') {
      // If at the end of the input or it's a single digit, move right
      if (target.selectionStart === target.value.length && field === 'effort') {
        e.preventDefault();
        const nextIndex = index + 1;
        if (nextIndex < inputs.length) {
          inputs[nextIndex].focus();
          inputs[nextIndex].select();
        }
      }
    } else if (e.key === 'ArrowLeft') {
      // If at the beginning of the input, move left
      if (target.selectionStart === 0 && field === 'need') {
        e.preventDefault();
        const prevIndex = index - 1;
        if (prevIndex >= 0) {
          inputs[prevIndex].focus();
          inputs[prevIndex].select();
        }
      }
    }
  };

  const getToggleStatus = (toggleName: string | null) => {
    if (!toggleName) return true;
    switch (toggleName) {
      case 'showSupportTickets': return showSupportTickets;
      case 'showSupportPerformance': return showSupportPerformance;
      case 'showJiraIntegration': return showJiraIntegration;
      case 'showAutomatedChangeLog': return showAutomatedChangeLog;
      case 'showContainerPipelines': return showContainerPipelines;
      case 'showContainerRegistry': return showContainerRegistry;
      case 'showVulnerabilityHeatmap': return showVulnerabilityHeatmap;
      case 'showOrphanedDetection': return showOrphanedDetection;
      case 'showVulnerabilityScan': return showVulnerabilityScan;
      case 'showAdvancedArchitecture': return showAdvancedArchitecture;
      case 'showArchitectureDiff': return showArchitectureDiff;
      case 'showPipelineSidebarDetails': return showPipelineSidebarDetails;
      case 'showPipelineTypeDropdown': return showPipelineTypeDropdown;
      case 'showDraftUpdates': return showDraftUpdates;
      case 'showDryRunUpdates': return showDryRunUpdates;
      case 'isFeatureDryRunLogEnabled': return isFeatureDryRunLogEnabled;
      case 'showReviewerDashboard': return showReviewerDashboard;
      case 'showErrorClustering': return showErrorClustering;
      case 'isInternalTeamView': return isInternalTeamView;
      default: return true;
    }
  };

  const filteredUserStories = useMemo(() => {
    return userStoriesData.filter(us => {
      const isActivated = getToggleStatus(us.toggle);
      
      if (!showDeactivatedRequirements && !isActivated) return false;

      const matchesSearch = (us.title || '').toLowerCase().includes(requirementsSearch.toLowerCase()) || 
                            (us.id || '').toLowerCase().includes(requirementsSearch.toLowerCase());
      const matchesType = requirementsTypeFilter.length === 0 || requirementsTypeFilter.includes(us.type);
      const matchesEpic = requirementsEpicFilter.length === 0 || requirementsEpicFilter.includes(us.epic);
      
      const isAssociated = us.toggle !== null;
      const matchesAssociation = requirementsAssociationFilter.length === 0 || 
                                 (requirementsAssociationFilter.includes('Associated') && isAssociated) ||
                                 (requirementsAssociationFilter.includes('Not associated') && !isAssociated);
      
      const matchesStatus = requirementsStatusFilter.length === 0 ||
                            (requirementsStatusFilter.includes('Active') && isActivated) ||
                            (requirementsStatusFilter.includes('Deactivated') && !isActivated);

      return matchesSearch && matchesType && matchesEpic && matchesAssociation && matchesStatus;
    });
  }, [featuresData, userStoriesData, requirementsSearch, requirementsTypeFilter, requirementsEpicFilter, requirementsAssociationFilter, requirementsStatusFilter, showDeactivatedRequirements, 
      showSupportTickets, showSupportPerformance, showJiraIntegration, showAutomatedChangeLog, showContainerPipelines, showContainerRegistry, 
      showVulnerabilityHeatmap, showOrphanedDetection, showVulnerabilityScan, showAdvancedArchitecture, showArchitectureDiff, 
      showPipelineSidebarDetails, showDryRunUpdates, isFeatureDryRunLogEnabled, showReviewerDashboard, showErrorClustering, isInternalTeamView]);

  const filteredFeatures = useMemo(() => {
    return featuresData.filter(f => {
      const isActivated = getToggleStatus(f.toggle);

      if (!showDeactivatedRequirements && !isActivated) return false;

      const matchesSearch = (f.title || '').toLowerCase().includes(requirementsSearch.toLowerCase()) || 
                            (f.id || '').toLowerCase().includes(requirementsSearch.toLowerCase());
      const matchesType = requirementsTypeFilter.length === 0 || requirementsTypeFilter.includes(f.type);
      const matchesEpic = requirementsEpicFilter.length === 0 || requirementsEpicFilter.includes(f.epic);

      const isAssociated = f.toggle !== null;
      const matchesAssociation = requirementsAssociationFilter.length === 0 || 
                                 (requirementsAssociationFilter.includes('Associated') && isAssociated) ||
                                 (requirementsAssociationFilter.includes('Not associated') && !isAssociated);
      
      const matchesStatus = requirementsStatusFilter.length === 0 ||
                            (requirementsStatusFilter.includes('Active') && isActivated) ||
                            (requirementsStatusFilter.includes('Deactivated') && !isActivated);
      
      const matchesPriority = requirementsPriorityFilter.length === 0 || requirementsPriorityFilter.includes(getPriorityInfo(f.need, f.effort).label);

      return matchesSearch && matchesType && matchesEpic && matchesAssociation && matchesStatus && matchesPriority;
    });
  }, [featuresData, requirementsSearch, requirementsTypeFilter, requirementsEpicFilter, requirementsAssociationFilter, requirementsStatusFilter, requirementsPriorityFilter, showDeactivatedRequirements,
      showSupportTickets, showSupportPerformance, showJiraIntegration, showAutomatedChangeLog, showContainerPipelines, showContainerRegistry, 
      showVulnerabilityHeatmap, showOrphanedDetection, showVulnerabilityScan, showAdvancedArchitecture, showArchitectureDiff, 
      showPipelineSidebarDetails, showDryRunUpdates, isFeatureDryRunLogEnabled, showReviewerDashboard, showErrorClustering, isInternalTeamView]);

  const groupedUserStories = useMemo(() => {
    const groups: Record<string, typeof userStoriesData> = {};
    filteredUserStories.forEach(us => {
      if (!groups[us.epic]) groups[us.epic] = [];
      groups[us.epic].push(us);
    });
    
    // Sort items within each group by ID (e.g., US1.1, US1.2)
    Object.values(groups).forEach(group => {
      group.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true, sensitivity: 'base' }));
    });

    // Sort epics by predefined order
    return Object.entries(groups).sort(([epicA], [epicB]) => {
      const epicOrder: Record<string, number> = {
        'Epic 0: App Shell & Global Components': 0,
        'Epic 1: Pipeline Management': 1,
        'Epic 2: Job Monitoring': 2,
        'Epic 3: Artifact Management': 3,
        'Epic 4: Dataset Management': 4,
        'Epic 5: Global Controls & Security': 5,
        'Epic 6: Container Registry': 6,
      };
      return (epicOrder[epicA] ?? 99) - (epicOrder[epicB] ?? 99);
    });
  }, [filteredUserStories]);

  const groupedFeatures = useMemo(() => {
    const groups: Record<string, typeof featuresData> = {};
    filteredFeatures.forEach(f => {
      if (!groups[f.epic]) groups[f.epic] = [];
      groups[f.epic].push(f);
    });

    // Sort items within each group
    Object.values(groups).forEach(group => {
      group.sort((a, b) => {
        if (!sortConfig) return a.id.localeCompare(b.id, undefined, { numeric: true, sensitivity: 'base' });
        
        const key = sortConfig.key as keyof typeof a;
        let valA = a[key] ?? '';
        let valB = b[key] ?? '';
        
        if (key === 'score' || key === 'effort' || key === 'need' || key === 'priority') {
          const numA = Number(valA);
          const numB = Number(valB);
          return sortConfig.direction === 'asc' ? numA - numB : numB - numA;
        }
        
        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }
        
        return sortConfig.direction === 'asc' 
          ? String(valA).localeCompare(String(valB), undefined, { numeric: true, sensitivity: 'base' })
          : String(valB).localeCompare(String(valA), undefined, { numeric: true, sensitivity: 'base' });
      });
    });

    // Sort epics by the ID of their first feature
    return Object.entries(groups).sort(([, itemsA], [, itemsB]) => {
      const idA = itemsA[0]?.id || '';
      const idB = itemsB[0]?.id || '';
      return idA.localeCompare(idB, undefined, { numeric: true, sensitivity: 'base' });
    });
  }, [filteredFeatures, sortConfig]);

