  const groupedContainers = useMemo(() => {
    return Array.from(
      mockContainers.reduce((acc, container) => {
        const existing = acc.get(container.name);
        if (!existing) {
          acc.set(container.name, {
            ...container,
            pipelineNames: container.pipelineName ? [container.pipelineName] : [],
            containerIds: [container.id],
            allTags: [{ tag: container.tag, vulnerabilities: container.vulnerabilities, created: container.created, size: container.size }],
            aggregatedVulnerabilities: { ...container.vulnerabilities }
          });
        } else {
          if (container.pipelineName && !existing.pipelineNames.includes(container.pipelineName)) {
            existing.pipelineNames.push(container.pipelineName);
          }
          existing.containerIds.push(container.id);
          existing.allTags.push({ tag: container.tag, vulnerabilities: container.vulnerabilities, created: container.created, size: container.size });
          
          // Aggregate vulnerabilities (take max for each level across tags)
          if (container.vulnerabilities) {
            existing.aggregatedVulnerabilities.critical = Math.max(existing.aggregatedVulnerabilities.critical, container.vulnerabilities.critical);
            existing.aggregatedVulnerabilities.high = Math.max(existing.aggregatedVulnerabilities.high, container.vulnerabilities.high);
            existing.aggregatedVulnerabilities.medium = Math.max(existing.aggregatedVulnerabilities.medium, container.vulnerabilities.medium);
            existing.aggregatedVulnerabilities.low = Math.max(existing.aggregatedVulnerabilities.low, container.vulnerabilities.low);
          }

          if (new Date(container.created) > new Date(existing.created)) {
            existing.created = container.created;
            existing.status = container.status;
            existing.size = container.size;
            existing.tag = container.tag;
            existing.id = container.id;
          }
        }
        return acc;
      }, new Map<string, any>()).values()
    ).map((group: any) => ({
      ...group,
      isOrphaned: group.pipelineNames.length === 0
    })) as any[];
  }, [mockContainers]);

