  const handleSupportRequest = async (itemId: string, itemName: string, status: string) => {
    const existing = supportRequests.find(r => r.itemId === itemId);
    if (existing) {
      setExistingTicketId(existing.id);
      return;
    }
    
    const ticketId = `TKT-${Math.floor(1000 + Math.random() * 9000)}`;
    
    const job = jobs.find(j => j.id === itemId);
    let category = 'General Issue';
    
    if (job?.errorType === 'Code') {
      category = 'Application Bug';
    } else if (job?.errorType === 'System') {
      category = 'Infrastructure';
    } else if (job?.errorType === 'Data') {
      category = 'Data Quality';
    }

    const newRequest = {
      id: ticketId,
      itemId,
      itemName,
      pipelineName: job?.pipeline || 'Unknown',
      status: 'Submitted',
      category,
      date: new Date().toISOString().split('T')[0],
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      jiraUrl: `https://jira.mrff.internal/browse/${ticketId}`,
      isArchived: false
    };
    setSupportRequests([newRequest, ...supportRequests]);
    setLastCreatedTicketId(ticketId);
    await handleCreateJiraTicket(itemId, itemName, status);
  };

