  const getPipelineStats = (pipelineName: string) => {
    const pipelineJobs = jobs.filter(j => j.pipeline === pipelineName);
    const total = pipelineJobs.length;
    const success = pipelineJobs.filter(j => j.status === 'Completed').length;
    const failed = pipelineJobs.filter(j => ['Code Error', 'System Error', 'Data Error', 'Failed'].includes(j.status)).length;
    const queued = pipelineJobs.filter(j => j.status === 'Queued').length;
    const paused = pipelineJobs.filter(j => j.status === 'Paused').length;
    const running = pipelineJobs.filter(j => j.status === 'Running').length;
    
    const errorTypes = pipelineJobs.reduce((acc, j) => {
      if (j.errorType) {
        acc[j.errorType] = (acc[j.errorType] || 0) + 1;
      }
      return acc;
    }, {} as Record<string, number>);

    const parseTimeToSeconds = (timeStr: string) => {
      if (!timeStr || timeStr === '0s') return 0;
      const parts = timeStr.split(' ');
      let totalSeconds = 0;
      parts.forEach(p => {
        if (p.endsWith('m')) totalSeconds += parseInt(p) * 60;
        if (p.endsWith('s')) totalSeconds += parseInt(p);
      });
      return totalSeconds;
    };

    const totalSeconds = pipelineJobs.reduce((acc, j) => acc + parseTimeToSeconds(j.time), 0);
    const avgSeconds = total > 0 ? Math.round(totalSeconds / total) : 0;
    const avgTime = `${Math.floor(avgSeconds / 60)}m ${avgSeconds % 60}s`;

    return { total, success, failed, queued, paused, running, errorTypes, avgTime };
  };

