  const getNextVersion = (currentVersion: string, type: 'update' | 'bugfix') => {
    if (!currentVersion) return 'v1.0.0';
    const parts = currentVersion.replace('v', '').split('.');
    if (parts.length !== 3) return currentVersion + '-new';
    
    let [major, minor, patch] = parts.map(Number);
    if (type === 'update') {
      minor += 1;
      patch = 0;
    } else {
      patch += 1;
    }
    return `v${major}.${minor}.${patch}`;
  };

